def get_kraken_signature(urlpath, data, secret, nonce):
    if urlpath.startswith('/derivatives'):
        urlpath = urlpath[len('/derivatives'):]
    encoded = (urllib.parse.urlencode(data) + nonce + urlpath).encode()
    message = hashlib.sha256(encoded).digest()

    mac = hmac.new(base64.b64decode(secret), message, hashlib.sha512)
    sigdigest = base64.b64encode(mac.digest())
    return sigdigest.decode()

