symbol_map = {}
for vals in obj["tickers"]:
    lastTime = vals.get('lastTime')
    last = vals.get('last')
    if last and lastTime:
        symbol_map[vals["symbol"]] = {
            'time': dateutil.parser.parse(lastTime),
            'price': float(last)
        }

if symbol_map:
    for asset in assets:
        vals = symbol_map.get(asset.ticker)
        if vals:
            asset.price_upsert(time=vals['time'], price=vals['price'])
